    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { n: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    const t = peek()
    if (!t) bad()
    if (t.k === 'num') { p++; return { n: 'num', v: t.v } }
    if (t.k === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) bad()
      p++
      return e
    }
    if (t.k === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++ } else {
          for (;;) {
            args.push(arg())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            bad()
          }
        }
        return { n: 'call', name: t.v.toUpperCase(), args }
      }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { n: 'bool', v: true }
      if (u === 'FALSE') return { n: 'bool', v: false }
      return { n: 'ref', a: parseAddr(t.v) }
    }
    bad()
  }
  function arg() {
    const t = peek()
    if (t && t.k === 'word' && toks[p + 1] && toks[p + 1].k === 'op' && toks[p + 1].v === ':') {
      const t2 = toks[p + 2]
      if (!t2 || t2.k !== 'word') bad()
      p += 3
      return { n: 'range', a: parseAddr(t.v), b: parseAddr(t2.v) }
    }
    return cmp()
  }
  const e = cmp()
  if (p !== toks.length) bad()
  return e
}

// ---- sheet
const cells = new Map() // key -> {addr, content, ast, kind}
function rangeCells(a, b) {
  const out = []
  const c1 = Math.min(a.c, b.c), c2 = Math.max(a.c, b.c), r1 = Math.min(a.r, b.r), r2 = Math.max(a.r, b.r)
  for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) out.push({ c, r })
  return out
}

const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
lines.forEach((raw, idx) => {
  const line = raw.replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') return
  const m = /^[^ \t]*/.exec(line)
  const addrTxt = m[0]
  let rest = line.slice(addrTxt.length)
  rest = rest.replace(/^[ \t]+/, '')
  const a = parseAddr(addrTxt)
  if (!a) fail(`error: line ${idx + 1}: invalid cell address ${addrTxt}`)
  if (cells.has(key(a))) fail(`error: line ${idx + 1}: cell ${fmtAddr(a)} is declared twice`)
  const cell = { addr: a, content: rest, ast: null }
  if (rest[0] === '=') {
    try { cell.ast = parse(rest.slice(1)) } catch { cell.ast = 'bad' }
  }
  cells.set(key(a), cell)
})
const sorted = [...cells.values()].sort((x, y) => key(x.addr) - key(y.addr))

if (mode === 'deps') {
  const out = []
  for (const cell of sorted) {
    const set = new Map()
    const add = (a) => { if (a) set.set(key(a), a) }
    const walk = (n) => {
      if (!n) return
      switch (n.n) {
        case 'ref': add(n.a); break
        case 'range': if (n.a && n.b) rangeCells(n.a, n.b).forEach(add); break
        case 'bin': walk(n.l); walk(n.r); break
        case 'un': walk(n.e); break
        case 'call': n.args.forEach(walk); break
      }
    }
    if (cell.ast && cell.ast !== 'bad') walk(cell.ast)
    const list = [...set.values()].sort((x, y) => key(x) - key(y))
    out.push(fmtAddr(cell.addr) + ':' + list.map((a) => ' ' + fmtAddr(a)).join(''))
  }
  process.stdout.write(out.map((l) => l + '\n').join(''))
} else {
  const memo = new Map()
  const busy = new Set()
  function cellValue(a) {
    const k = key(a)
    if (memo.has(k)) return memo.get(k)
    const cell = cells.get(k)
    if (!cell) return num(0)
    if (busy.has(k)) return err('#CYCLE!')
    busy.add(k)
    let v
    const s = cell.content
    if (cell.ast) v = cell.ast === 'bad' ? err('#ERR!') : evalNode(cell.ast)
    else if (s === '') v = num(0)
    else if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) v = num(Number(s))
    else if (ERRS.includes(s)) v = err(s)
    else v = { t: 's', v: s }
    busy.delete(k)
    memo.set(k, v)
    return v
  }
  const finite = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))
  function toNum(v) {
    if (v.t === 'n') return v
    if (v.t === 'b') return num(v.v ? 1 : 0)
    return err('#VALUE!')
  }
  const rank = { n: 0, s: 1, b: 2 }
  function cmpCP(a, b) {
    const x = Array.from(a), y = Array.from(b)
    for (let i = 0; i < Math.min(x.length, y.length); i++) {
      const d = x[i].codePointAt(0) - y[i].codePointAt(0)
      if (d) return d
    }
    return x.length - y.length
  }
  function compare(a, b) {
    if (a.t !== b.t) return rank[a.t] - rank[b.t]
    if (a.t === 's') return cmpCP(a.v, b.v)
    if (a.t === 'b') return (a.v ? 1 : 0) - (b.v ? 1 : 0)
    return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  }
  // values of an argument: array of values
  function argValues(n) {
    if (n.n === 'range') {
      if (!n.a || !n.b) return [err('#REF!')]
      return rangeCells(n.a, n.b).map(cellValue)
    }
    return [evalNode(n)]
  }
  function scalarArg(n) {
    const vs = argValues(n)
    const e = vs.find((v) => v.t === 'e')
    if (e) return e
    return vs.length === 1 ? vs[0] : err('#VALUE!')
  }
  const arity = { SUM: [1, Infinity], MIN: [1, Infinity], MAX: [1, Infinity], COUNT: [1, Infinity], AVG: [1, Infinity], ABS: [1, 1], IF: [3, 3] }
  function evalNode(n) {
    switch (n.n) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'ref': return n.a ? cellValue(n.a) : err('#REF!')
      case 'un': {
        const v = evalNode(n.e)
        if (v.t === 'e') return v
        const x = toNum(v)
        if (x.t === 'e') return x
        return n.op === '-' ? num(-x.v) : x
      }
      case 'bin': {
        const l = evalNode(n.l)
        const r = evalNode(n.r)
        if (l.t === 'e') return l
        if (r.t === 'e') return r
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          const c = compare(l, r)
          const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
          return { t: 'b', v: res }
        }
        const a = toNum(l), b = toNum(r)
        if (a.t === 'e') return a
        if (b.t === 'e') return b
        switch (n.op) {
          case '+': return finite(a.v + b.v)
          case '-': return finite(a.v - b.v)
          case '*': return finite(a.v * b.v)
          case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
          case '^': return finite(Math.pow(a.v, b.v))
        }
        return err('#ERR!')
      }
      case 'range': return err('#ERR!')
      case 'call': {
        const ar = arity[n.name]
        if (!ar) return err('#NAME?')
        if (n.args.length < ar[0] || n.args.length > ar[1]) return err('#ERR!')
        if (n.name === 'IF') {
          const c = scalarArg(n.args[0])
          if (c.t === 'e') return c
          let truth
          if (c.t === 'b') truth = c.v
          else if (c.t === 'n') truth = c.v !== 0
          else return err('#VALUE!')
          return scalarArg(n.args[truth ? 1 : 2])
        }
        if (n.name === 'ABS') {
          const v = scalarArg(n.args[0])
          if (v.t === 'e') return v
          const x = toNum(v)
          return x.t === 'e' ? x : num(Math.abs(x.v))
        }
        const vals = []
        for (const a of n.args) vals.push(...argValues(a))
        const e = vals.find((v) => v.t === 'e')
        if (e) return e
        if (n.name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
        const nums = []
        for (const v of vals) {
          const x = toNum(v)
          if (x.t === 'e') return x
          nums.push(x.v)
        }
        switch (n.name) {
          case 'SUM': return finite(nums.reduce((s, x) => s + x, 0))
          case 'MIN': return num(nums.reduce((s, x) => (x < s ? x : s), Infinity))
          case 'MAX': return num(nums.reduce((s, x) => (x > s ? x : s), -Infinity))
          case 'AVG': return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
        }
      }
    }
    return err('#ERR!')
  }
  const out = sorted.map((cell) => {
    const v = cellValue(cell.addr)
    let s
    if (v.t === 'n') s = String(Number(v.v.toPrecision(10)))
    else if (v.t === 'b') s = v.v ? 'TRUE' : 'FALSE'
    else s = v.v
    return `${fmtAddr(cell.addr)}=${s}\n`
  })
  process.stdout.write(out.join(''))
}
